      for (var i = 0; i < len; i++) {
        pixel = this.pixels[i];
        scale = fov / (fov + pixel.z);
        x2d = pixel.x * scale + this.W / 2;
        y2d = pixel.y * scale + this.H / 1.5;
        if (x2d >= 0 && x2d <= this.W && y2d >= 0 && y2d <= this.H) {
          c = (Math.round(y2d) * imageData.width + Math.round(x2d)) * 4;
