          imageData.data[c + 2] = 181;
          imageData.data[c + 3] = 255;
        }
        pixel.z -= 0.4;
        pixel.y = this.H / 14 + Math.sin(i / len * 15 + ts / 450) * 10; //幅度
        if (pixel.z < -fov) pixel.z += 2 * fov;
      }
      this.ctx.putImageData(imageData, 0, 0);
